import logging


def docstring_parameter(*sub):
    """Decorator allowing formatted docstrings"""
    def _fun_with_formated_docstring(obj):
        obj.__doc__ = obj.__doc__.format(*sub)
        return obj
    return _fun_with_formated_docstring


plugin_usage = """
ta_ue_plugin_rtg doesn't work standalone - it is plugin. You need ute_ue first:
pip install ute_ue
Then ensure plugin is installed as well:
pip install ta_ue_plugin_rtg

ta_ue_plugin_rtg also relies on elixir library UEx: (http://nas-krk.krk-lab.nsn-rdnet.net/~awr001/uex/uex/overview.html)
and therefore requires a compatible ta_ue_plugin_rtg_server elixir application to be installed.
ta_ue_plugin_rtg_server is installed together with RTG package.

Please make sure that ta_ue_plugin_rtg and ta_ue_plugin_rtg_server versions match, otherwise your test will start with a warning message.
On UTE testline versions are automatically aligned by RTG Agent.

to print ta_ue_plugin_rtg version run:
pip list | grep ta-ue-plugin-rtg

to print ta_ue_plugin_rtg_server version run:
app=ta_ue_plugin_rtg_server; unzip -p /opt/rtg/lib/uex/$app.ez $app/ebin/$app.app | grep -Po '{vsn,"\\K\\d+\\.\\d+\\.\\d+')

to align ta_ue_plugin_rtg version with ta_ue_plugin_rtg_server version run:
app=ta_ue_plugin_rtg_server; version=$(unzip -p /opt/rtg/lib/uex/$app.ez $app/ebin/$app.app | grep -Po '{vsn,"\\K\\d+\\.\\d+\\.\\d+')
pip install -U ta_ue_plugin_rtg==$version

Note: For traffic related keywords like 'Start Data Transfer' eTGR elixir application need to be up and running on TGRs.
Make sure the 'etgr=on' flag is present in [tgr_X] section of your rtg.ini.
Open up RTG Executor console ('telnet 0 1234' by default) and run:
RTG> config update
RTG> config remote update tgr
"""

plugin_info = """
Rtg implementation of Abstract UE (ute_ue library).

development project and code repository:
    - Python client/plugin: https://wrgitlab.int.net.nokia.com/abstract_library/ta_ue_plugin_rtg
    - Elixir server: https://wrgitlab.int.net.nokia.com/tsex/ta_ue_plugin_rtg_server

ute_ue JIRA: https://jiradc.int.net.nokia.com/projects/TAUE

ute_ue wiki: https://wrgitlab.int.net.nokia.com/abstract_library/ute_ue/wikis/home

developers mailing list: I_ABSTRACT_LIBRARY_DEV@internal.nsn.com

Ue configuration may be given either as robot variable or environment variable - details see ute_ue documentation.

Configuration file examples: see ta_ue_plugin_rtg/example/config/ folder
or search ta_ue_plugin_rtg repository for *.yml files

Test Cases examples are available in:
    - ute_ue/example/
    - ta_ue_plugin_rtg/example/
"""


class ta_ue_plugin_rtg(object):
    """Rtg Implementation of Abstract UE (ute_ue library)"""

    ROBOT_LIBRARY_SCOPE = 'GLOBAL'

    @docstring_parameter(plugin_usage)
    def show_plugin_usage(self):
        """
        Put into logs usage of this plugin:

        {}

        :return: usage string
        """
        logger = logging.getLogger('ute_ue')
        logger.warning(plugin_usage)
        return plugin_usage

    @docstring_parameter(plugin_info)
    def show_plugin_info(self):
        """
        Put into logs information about this plugin:

        {}

        :return: information string
        """
        logger = logging.getLogger('ute_ue')
        logger.warning(plugin_info)
        return plugin_info


if __name__ == '__main__':
    plugin = ta_ue_plugin_rtg()
    print(plugin.show_plugin_usage())               # noqa: T201
    print("------------------------------------")   # noqa: T201
    print(plugin.show_plugin_info())                # noqa: T201
    print("------------------------------------")   # noqa: T201
